@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + name : string
  + phoneNumber : string
  + email : string
}

class Contract {
  + number : int
  + signingDate : date
  + insuredAmount : double
  + policyType : PolicyType
}

class Company {}

abstract class Policy {
  + text : string
}

class Life {}
class CarLiability {}
class Theft {}

class ClaimCase {
  + caseNumber : int
  + startDate : date
  + status : ClaimStatus
}

enum PolicyType {
  life
  car_liability
  theft
}

enum ClaimStatus {
  open
  under_review
  approved
  paid
}

Customer "1" -- "1..*" Contract
Company -- Contract
Company "1" o-- "1..*" Policy
Contract "0..*" -- "1" Policy
Life --|> Policy
CarLiability --|> Policy
Theft --|> Policy

Broker "1" -- "1..*" Customer
Customer "1" -- "1" Broker

Customer "1" -- "0..*" ClaimCase
ClaimCase "1" -- "*" EstimatorReport

EstimatorReport "1" -- "1" ClaimCase

Company "1" -- "0..*" ClaimCase

@enduml

